/** Owns recipe and batch editor mutations so the screen manager remains an orchestration boundary. */
internal class RecipeBatchCommandHandler(
    private val database: LocalDatabase,
    private val loadWorkspace: suspend () -> Workspace,
    private val now: () -> Instant,
    private val today: () -> LocalDate,
) {
    suspend fun saveRecipe(command: ScreenCommand) {
        require(SproutPaceCatalog.cultures.none { it.id.value == command.subject() }) { "Built-in guides are read-only" }
        val culture = SproutPaceCatalog.cultures.firstOrNull { it.id.value == command.required("cultureId") }
            ?: error("Unknown culture")
        val existing = loadWorkspace().recipes.firstOrNull { it.id.value == command.subject() }
        val stages = if (command.arguments.containsKey("stage1")) {
            command.recipeDraftStages(existing, culture)
        } else {
            existing?.stages ?: error("Recipe stage configuration is required")
        }
        database.saveRecipe(UserGrowRecipe(
            id = RecipeId(command.subject()),
            name = command.required("name"),
            cultureId = culture.id,
            stages = stages,
            density = existing?.takeIf { it.cultureId == culture.id }?.density ?: culture.seedDensity,
            substrate = command.required("substrate"),
            supplier = command.updatedOptional("supplier", existing?.supplier),
            cultivar = command.updatedOptional("cultivar", existing?.cultivar),
            seedLot = command.updatedOptional("seedLot", existing?.seedLot),
            germinationPercentage = if (command.arguments.containsKey("germinationPercentage")) {
                command.optionalPercentage("germinationPercentage")
            } else existing?.germinationPercentage,
        ))
    }

    suspend fun duplicateRecipe(command: ScreenCommand) {
        val workspace = loadWorkspace()
        val targetId = RecipeId(command.required("newId"))
        require(workspace.recipes.none { it.id == targetId })
        val source = workspace.recipes.firstOrNull { it.id.value == command.subject() }
        val duplicate = if (source != null) {
            source.copy(id = targetId, name = command.optional("name") ?: source.name)
        } else {
            val culture = SproutPaceCatalog.cultures.firstOrNull { it.id.value == command.subject() }
                ?: throw LocalDataException(LocalDataErrorKey.INVALID_COMMAND)
            UserGrowRecipe(
                id = targetId,
                name = command.required("name"),
                cultureId = culture.id,
                stages = culture.stages.map { RecipeStage(it.stage, it.duration, guidanceKey = it.instructionKey) },
                density = culture.seedDensity,
                substrate = command.required("substrate"),
            )
        }
        database.saveRecipe(duplicate)
    }

    suspend fun saveBatch(command: ScreenCommand) {
        val workspace = loadWorkspace()
        val recipeId = command.arguments["recipeId"]
        val recipeSnapshot = recipeSnapshot(workspace, recipeId, command.arguments["cultureId"])
        val tray = workspace.trays.firstOrNull { it.id.value == command.required("trayId") }
            ?: error("Unknown tray")
        val sourceRecipe = workspace.recipes.firstOrNull { it.id.value == recipeId }
        val recommended = MeasurementEngine.recommendedSeedMass(tray.shape, recipeSnapshot.density)
        val plannedSowDate = command.optional("plannedSowDate")?.let(LocalDate::parse) ?: today()
        val timeZoneId = command.optional("timeZoneId") ?: DEFAULT_TIME_ZONE
        val batchId = BatchId(command.subject())
        database.saveBatch(GrowBatch(
            id = batchId,
            recipe = recipeSnapshot,
            tray = TraySnapshot(tray.name, tray.shape),
            substrateSnapshot = command.optional("substrate") ?: sourceRecipe?.substrate
                ?: command.required("substrate"),
            recommendedSeedMass = recommended,
            actualSeedMass = command.optional("actualSeedMassGrams")?.let(::positiveGrams) ?: recommended,
            state = BatchState.PLANNED,
            placement = Placement.None,
            events = emptyList(),
            actions = BatchPlanningEngine.plannedActions(
                batchId, recipeSnapshot.stages, plannedSowDate, command.fixedStageDates(), timeZoneId,
            ),
            supplier = command.optional("supplier") ?: sourceRecipe?.supplier,
            cultivar = command.optional("cultivar") ?: sourceRecipe?.cultivar,
            seedLot = command.optional("seedLot") ?: sourceRecipe?.seedLot,
            germinationPercentage = command.optionalPercentage("germinationPercentage")
                ?: sourceRecipe?.germinationPercentage,
            plannedSowDate = plannedSowDate,
            cultureIdSnapshot = command.optional("cultureId")?.let(::CultureId)
                ?: sourceRecipe?.cultureId ?: recipeSnapshot.builtInCultureId,
        ))
    }

    suspend fun correctBatch(command: ScreenCommand) {
        val workspace = loadWorkspace()
        val original = workspace.batch(command.subject())
        val tray = selectedTray(command, workspace)
        val plannedSowDate = command.optional("plannedSowDate")?.let(LocalDate::parse) ?: original.plannedSowDate
        val timeZoneId = command.optional("timeZoneId") ?: original.timeZoneId() ?: DEFAULT_TIME_ZONE
        val fixedDates = correctedFixedDates(command, original)
        val fields = correctedFields(command, original, workspace, tray, plannedSowDate)
        val events = BatchPlanningEngine.correctActualEventDates(fields, command.correctedActualDates())
        val scheduled = events.withCorrectedSchedule(plannedSowDate, fixedDates, timeZoneId)
        val corrected = rebuildDependentFutureActions(command, scheduled)
        database.saveBatch(corrected)
    }

    private fun recipeSnapshot(workspace: Workspace, recipeId: String?, cultureId: String?): RecipeSnapshot = when {
        recipeId != null -> workspace.recipes.firstOrNull { it.id.value == recipeId }?.let {
            RecipeSnapshot(it.id, it.cultureId, it.name, it.stages, it.density)
        } ?: error("Unknown recipe")
        cultureId != null -> SproutPaceCatalog.cultures.firstOrNull { it.id.value == cultureId }?.let {
            RecipeSnapshot(
                null,
                it.id,
                null,
                it.stages.map { stage -> RecipeStage(stage.stage, stage.duration, stage.instructionKey) },
                it.seedDensity,
            )
        } ?: error("Unknown culture")
        else -> error("recipeId or cultureId is required")
    }

    private fun selectedTray(command: ScreenCommand, workspace: Workspace): TraySizePreset? =
        command.optional("trayId")?.let { trayId ->
            workspace.trays.firstOrNull { it.id.value == trayId } ?: error("Unknown tray")
        }

    private fun correctedFields(
        command: ScreenCommand,
        batch: GrowBatch,
        workspace: Workspace,
        tray: TraySizePreset?,
        plannedSowDate: LocalDate?,
    ): GrowBatch = batch.copy(
        tray = tray?.let { TraySnapshot(it.name, it.shape) } ?: batch.tray,
        substrateSnapshot = command.optional("substrate") ?: batch.substrateSnapshot,
        recommendedSeedMass = tray?.let { MeasurementEngine.recommendedSeedMass(it.shape, batch.recipe.density) }
            ?: batch.recommendedSeedMass,
        actualSeedMass = command.optional("actualSeedMassGrams")?.let(::positiveGrams) ?: batch.actualSeedMass,
        placement = if (command.arguments.containsKey("zoneId")) placement(command, workspace) else batch.placement,
        supplier = command.updatedOptional("supplier", batch.supplier),
        cultivar = command.updatedOptional("cultivar", batch.cultivar),
        seedLot = command.updatedOptional("seedLot", batch.seedLot),
        germinationPercentage = if (command.arguments.containsKey("germinationPercentage")) {
            command.optionalPercentage("germinationPercentage")
        } else batch.germinationPercentage,
        plannedSowDate = plannedSowDate,
        cultureIdSnapshot = command.optional("cultureId")?.let(::CultureId) ?: batch.cultureIdSnapshot,
    )

    private fun correctedFixedDates(command: ScreenCommand, batch: GrowBatch): Map<GrowStage, LocalDate> =
        if (FIXED_DATE_FIELDS.any(command.arguments::containsKey)) {
            command.fixedStageDates()
        } else {
            batch.actions.mapNotNull { action ->
                val due = action.due as? DueMoment.CivilTime

            "circle" -> FIRST_RUN_ARGUMENTS + "diameterCm"
            else -> error("Unknown tray shape")
        }
        require(command.arguments.keys == expectedArguments) { "Unexpected first-run setup arguments" }
        val shape = when (shapeName) {
            "rectangle" -> TrayShape.Rectangle(command.double("widthCm"), command.double("lengthCm"))
            "circle" -> TrayShape.Circle(command.double("diameterCm"))
            else -> error("Unknown tray shape")
        }
        val cultures = command.required("cultureIds")
            .split(',')
            .map(String::trim)
            .filter(String::isNotBlank)
            .distinct()
            .map(::CultureId)
        require(cultures.isNotEmpty() && cultures.all { it in SproutPaceCatalog.cultureIds }) {
            "At least one known culture is required"
        }
        val mode = when (command.required("mode")) {
            "cadence" -> HarvestPlanMode.CADENCE
            "continuous_queue" -> HarvestPlanMode.CONTINUOUS_QUEUE
            else -> error("Unknown plan mode")
        }
        val zone = GrowZone(
            GrowZoneId(FIRST_RUN_ZONE_ID),
            command.required("zoneName"),
            type,
            capacity,
        )
        val tray = TraySizePreset(
            TraySizePresetId(FIRST_RUN_TRAY_ID),
            command.required("trayName"),
            shape,
        )
        val plan = HarvestPlan(
            HarvestPlanId(FIRST_RUN_PLAN_ID),
            today(),
            HarvestCadenceDays(command.int("cadenceDays")),
            cultures,
            mode,
        )

        val current = database.snapshot()
        val zones = current.zones.filterNot { it.id == zone.id } + zone
        val trays = current.trayPresets.filterNot { it.id == tray.id } + tray
        val plans = current.plans.filterNot { it.id == plan.id } + plan
        val manifest = SnapshotValidation.manifest(
            zones,
            trays,
            current.recipes,
            current.batches,
            plans,
            current.observations,
            current.manifest.photoIntegrity,
        )
        database.replace(
            current.copy(
                manifest = manifest,
                zones = zones,
                trayPresets = trays,
                plans = plans,
            ),
        )
    }

    private suspend fun saveZone(command: ScreenCommand) {
        database.saveZone(GrowZone(
            GrowZoneId(command.subject()), command.required("name"), command.enum("type"), command.int("capacity"),
        ))
    }

    private suspend fun saveTray(command: ScreenCommand) {
        val shape = when (command.required("shape").lowercase()) {
            "rectangle" -> TrayShape.Rectangle(command.double("widthCm"), command.double("lengthCm"))
            "circle" -> TrayShape.Circle(command.double("diameterCm"))
            else -> error("Unknown tray shape")
        }
        database.saveTrayPreset(TraySizePreset(TraySizePresetId(command.subject()), command.required("name"), shape))
    }

    private suspend fun saveRecipe(command: ScreenCommand) = recipeBatchCommands.saveRecipe(command)

    private suspend fun duplicateRecipe(command: ScreenCommand) = recipeBatchCommands.duplicateRecipe(command)

    private suspend fun saveBatch(command: ScreenCommand) = recipeBatchCommands.saveBatch(command)

    private suspend fun correctBatch(command: ScreenCommand) = recipeBatchCommands.correctBatch(command)

    private suspend fun repeatBatch(command: ScreenCommand) {
        val workspace = loadWorkspace()
        val source = workspace.batch(command.subject())
        val newId = BatchId(command.required("newId"))
        require(workspace.batches.none { it.id == newId })
        database.saveBatch(source.repeatedAs(newId))
    }

    private suspend fun changeBatch(
        command: ScreenCommand,
        change: suspend (GrowBatch) -> com.sedsoftware.sproutpace.domain.model.BatchChange,
    ) {
        val batch = loadWorkspace().batch(command.subject())
        database.saveBatch(change(batch).batch)
    }

    private fun existingEvent(batch: GrowBatch, eventId: StageEventId) =
        batch.events.firstOrNull { it.id == eventId }?.let { com.sedsoftware.sproutpace.domain.model.BatchChange(batch) }

    private suspend fun updateAction(command: ScreenCommand, transform: (ScheduledAction) -> ScheduledAction) {
        val actionId = ScheduledActionId(command.subject())
        val workspace = loadWorkspace()
        val batch = workspace.batches.firstOrNull { candidate -> candidate.actions.any { it.id == actionId } } ?: error("Unknown action")
        val current = batch.actions.first { it.id == actionId }
        if (current.status != ScheduledActionStatus.PENDING) return
        val changed = transform(current)
        if (changed == current) return
        val updated = batch.copy(actions = batch.actions.map { if (it.id == actionId) changed else it })
        database.saveBatch(updated)
    }

    private suspend fun scheduleSoakTarget(command: ScreenCommand) {
        val workspace = loadWorkspace()
        val batch = workspace.batch(command.subject())
        val actionId = ScheduledActionId(command.arguments["actionId"] ?: "soak:${batch.id.value}")
        val action = ScheduledAction(actionId, batch.id, GrowStage.SOAKING, DueMoment.ElapsedTarget(command.instant("dueAt")))
        database.saveBatch(batch.copy(actions = (batch.actions.filterNot { it.id == actionId } + action)))
    }

    private suspend fun updateAllCivilActions(timeZoneId: String) {
        require(timeZoneId.isNotBlank())
        TimeZone.of(timeZoneId)
        val snapshot = database.snapshot()
        database.replace(snapshot.copy(batches = snapshot.batches.map { batch ->
            batch.copy(actions = batch.actions.map { SchedulingEngine.afterTimeZoneChange(it, timeZoneId) })
        }))
    }

    private suspend fun savePlan(command: ScreenCommand) {
        val cultures = command.required("cultureIds").split(',').map(String::trim).filter(String::isNotBlank).map(::CultureId)
        require(cultures.all { it in SproutPaceCatalog.cultureIds }) { "Unknown culture" }
        val existing = loadWorkspace().plans.firstOrNull { it.id.value == command.subject() }
        database.savePlan(HarvestPlan(
            HarvestPlanId(command.subject()),
            command.arguments["anchorDate"]?.let { LocalDate.parse(it) } ?: existing?.anchorDate ?: today(),
            HarvestCadenceDays(command.int("cadenceDays")), cultures,
            command.enum("mode"), command.arguments["paused"]?.toBooleanStrictOrNull() ?: existing?.paused ?: false,
        ))
    }

    private suspend fun pausePlan(command: ScreenCommand, paused: Boolean) {
        val plan = loadWorkspace().plans.firstOrNull { it.id.value == command.subject() } ?: error("Unknown plan")
        database.savePlan(plan.copy(paused = paused))
    }

    private suspend fun closeBatch(command: ScreenCommand) {
        val batch = loadWorkspace().batch(command.subject())
        val occurredAt = command.instant("occurredAt")
        val outcome = when (command.arguments["outcome"]?.lowercase() ?: command.operation) {
            "harvested", "close-harvest" -> BatchOutcome.Harvested(
                occurredAt,
                command.arguments["actualMassGrams"]?.let { PositiveGrams(it.toDoubleOrNull() ?: error("Invalid actualMassGrams")) },
                command.arguments["assessment"]?.let { enumValue<com.sedsoftware.sproutpace.domain.model.OutcomeAssessment>(it) },
                command.arguments["note"],
            )
            "failed", "close-failed" -> BatchOutcome.Failed(occurredAt, command.arguments["reason"], command.arguments["note"])
            "abandoned", "close-abandoned" -> BatchOutcome.Abandoned(occurredAt, command.arguments["reason"], command.arguments["note"])
            else -> error("Unknown outcome")
        }
        if (batch.outcome == outcome) return
        database.saveBatch(BatchLifecycleEngine.close(batch, outcome).batch)
    }

    private suspend fun recordActualMass(command: ScreenCommand) {
        val batch = loadWorkspace().batch(command.subject())
        val mass = command.arguments["actualMassGrams"]
            ?.takeIf(String::isNotBlank)
            ?.let { PositiveGrams(it.toDoubleOrNull() ?: error("Invalid actualMassGrams")) }
        database.saveBatch(BatchLifecycleEngine.recordActualHarvestMass(batch, mass))
    }

