)

internal fun GrowZone.occupancy(batches: List<GrowBatch>) = ZoneOccupancy(
    zoneId = id.value,
    zoneName = name,
    type = type,
    occupied = batches.count { it.state.occupiesPlace && (it.placement as? Placement.Assigned)?.zoneId == id },
    capacity = capacity,
)

/** Planned starts add demand; a predicted harvest never silently frees an occupied tray. */
internal fun GrowZone.futureConflict(batches: List<GrowBatch>, today: LocalDate): ZoneFutureConflict? {
    val assigned = batches.filter { (it.placement as? Placement.Assigned)?.zoneId == id }
    val projected = assigned.filter { it.state.occupiesPlace }.map { Occupancy(id, it.id) }.toMutableList()
    val starts = assigned.filter { it.state == BatchState.PLANNED || it.state == BatchState.SOAKING }
        .mapNotNull { batch -> batch.plannedSowDate?.takeIf { it > today }?.let { it to batch } }
        .groupBy({ it.first }, { it.second }).entries.sortedBy { it.key }
    for ((date, starting) in starts) {
        val decision = CapacityEngine.validate(this, projected, additionalPlaces = starting.size, date = date)
        if (decision is CapacityDecision.NeedsResolution) {
            return ZoneFutureConflict(date, projected.size + starting.size, capacity)
        }
        projected += starting.map { Occupancy(id, it.id) }
    }
    return null
}

internal fun Workspace.suggestion(id: String?, today: LocalDate): BatchSuggestion? {
    if (id == null) return null
    return plans.firstNotNullOfOrNull { plan ->
        PlannerEngine.suggestions(plan, SUGGESTION_COUNT) { _, _ -> CapacityDecision.Feasible }
            .firstOrNull { it.id == id && !coversSuggestion(it) }
            ?: PlannerEngine.nextContinuousSuggestion(plan, today) { _, _ -> CapacityDecision.Feasible }
                ?.takeIf { it.id == id && !coversSuggestion(it) }
    }
}

/** A saved fixed harvest target fulfills a plan slot, even when its sow date was adjusted. */
internal fun Workspace.coversSuggestion(suggestion: BatchSuggestion): Boolean = batches.any { batch ->
    batch.cultureIdSnapshot == suggestion.cultureId && batch.actions.any { action ->
        action.stage == GrowStage.READY_FOR_HARVEST && action.userFixed &&
            (action.due as? DueMoment.CivilTime)?.localDateTime?.date == suggestion.targetHarvestDate
    }
}

internal fun BatchSuggestion.sowDate(timeZoneId: String): LocalDate {
    val culture = SproutPaceCatalog.cultures.first { it.id == cultureId }
    return BatchPlanningEngine.sowDateForHarvest(
        culture.stages.map { RecipeStage(it.stage, it.duration, it.instructionKey) }, targetHarvestDate, timeZoneId,
    )
}

